window.__r = {
  chat() { const s = window.__ensemble.getState(); return s.chats.find(c => c.id === s.chatId) },
  state() {
    const c = window.__r.chat(); if (!c) return 'no chat';
    const g = c.goal; const ls = c.loops || [];
    return (g ? `goal ${g.status} r${g.round}/${g.maxRounds}${g.checking ? ' checking' : ''} log${g.log.length}${g.note ? ' note="' + g.note.slice(0, 60) + '"' : ''}` : 'no goal') +
      ' | ' + ls.map(l => `loop ${l.status} runs${l.runs}${l.running ? ' running' : ''} next=${l.nextAt ? Math.round((l.nextAt - Date.now()) / 1000) + 's' : '-'}${l.last ? ' last="' + l.last.slice(0, 40) + '"' : ''}`).join(', ') +
      ' | bar=' + !!document.querySelector('[data-auto-bar]');
  },
  async until(fn, ms = 20000) {
    const t0 = Date.now();
    while (Date.now() - t0 < ms) { try { if (fn(window.__r.chat())) return Date.now() - t0 } catch (e) {} await new Promise(r => setTimeout(r, 100)); }
    return 'TIMEOUT';
  },
  click(label) {
    const b = document.querySelector('[data-auto-bar] button[aria-label="' + label + '"]') || [...document.querySelectorAll('[data-auto-bar] button')].find(b => b.textContent.trim() === label);
    if (b) b.click();
    return !!b;
  },
  top() { const el = document.querySelector('.overflow-y-auto.h-full'); if (el) el.scrollTop = 0; return !!el },
};
return 'setup';

const out = [];
for (let i = 0; i < 10; i++) {
  if (window.__ensemble.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  out.push(b.textContent.trim().slice(0, 30));
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'clicked: ' + out.join(' > ') + ' | onboarded=' + window.__ensemble.getState().settings.onboarded;
